// Parse Whale Alert API response and normalise events
// ES5/ASCII only
var item = $input.item.json;
var txns = item.transactions || [];

if (!txns.length) {
  return [{ json: { hasAlerts: false, reason: 'no_transactions', count: 0, events: [] } }];
}

var events = [];
for (var i = 0; i < txns.length; i++) {
  var t = txns[i];
  // Skip exchange-to-exchange (low market impact)
  if (t.from.owner_type === 'exchange' && t.to.owner_type === 'exchange') continue;

  var fromType = t.from.owner_type || 'unknown';
  var toType   = t.to.owner_type   || 'unknown';
  var fromName = t.from.owner || fromType;
  var toName   = t.to.owner   || toType;
  var symbol   = (t.symbol || '').toUpperCase();
  var amtUsd   = t.amount_usd || 0;

  // Determine alert type
  var alertType = 'transfer';
  if (toType === 'exchange')   alertType = 'exchange_inflow';
  if (fromType === 'exchange') alertType = 'exchange_outflow';
  if (toType === 'burn')       alertType = 'burn';
  if (fromType === 'mint' || toType === 'mint') alertType = 'mint';

  // Format USD amount
  var amtStr;
  if (amtUsd >= 1e9)      amtStr = '$' + (amtUsd / 1e9).toFixed(1) + 'B';
  else if (amtUsd >= 1e6) amtStr = '$' + (amtUsd / 1e6).toFixed(1) + 'M';
  else                    amtStr = '$' + Math.round(amtUsd).toLocaleString();

  // Format token amount
  var amt = t.amount || 0;
  var amtFmt;
  if (amt >= 1e9)      amtFmt = (amt / 1e9).toFixed(2) + 'B';
  else if (amt >= 1e6) amtFmt = (amt / 1e6).toFixed(2) + 'M';
  else if (amt >= 1e3) amtFmt = (amt / 1e3).toFixed(1) + 'K';
  else                 amtFmt = String(Math.round(amt));

  // Build human-readable description
  var desc = amtFmt + ' ' + symbol + ' (' + amtStr + ') moved from ' + fromName + ' to ' + toName;

  // Market impact assessment
  var impact = 'neutral';
  if (alertType === 'exchange_inflow')
    impact = amtUsd >= 10e6 ? 'bearish' : 'neutral';
  if (alertType === 'exchange_outflow')
    impact = amtUsd >= 10e6 ? 'bullish' : 'neutral';

  events.push({
    transaction_hash: t.hash || '',
    blockchain:       t.blockchain || '',
    symbol:           symbol,
    amount:           amt,
    amount_usd:       amtUsd,
    amount_formatted: amtFmt,
    amount_usd_formatted: amtStr,
    from_owner_type:  fromType,
    from_owner:       fromName,
    to_owner_type:    toType,
    to_owner:         toName,
    alert_type:       alertType,
    description:      desc,
    impact:           impact,
    timestamp:        new Date((t.timestamp || 0) * 1000).toISOString(),
    url:              'https://whale-alert.io/transaction/' + (t.blockchain || '') + '/' + (t.hash || '')
  });
}

// Sort by amount_usd desc
events.sort(function(a, b) { return b.amount_usd - a.amount_usd; });

return [{ json: { hasAlerts: events.length > 0, count: events.length, events: events } }];

// Build ingest payload and X tweet for the top alert
var data = $input.item.json;
var events = data.events || [];

// POST payload to AlphaForgeAI ingest
var payload = JSON.stringify({ schema_version: 1, events: events });

// Pick top alert for X post (largest by USD value)
var top = events[0];
var EMOJI = { bullish: '\uD83D\uDCC8', bearish: '\uD83D\uDCC9', neutral: '\u26AA' };
var emoji = EMOJI[top.impact] || EMOJI.neutral;

// Format tweet
var impactLabel = top.impact.charAt(0).toUpperCase() + top.impact.slice(1);
var tweet = '\uD83D\uDC33 Whale Alert\n' +
  emoji + ' ' + top.description + '\n\n' +
  'Alert type: ' + top.alert_type.replace(/_/g, ' ') + '\n' +
  'Market signal: ' + impactLabel + '\n\n' +
  top.url + '\n\n' +
  '$' + top.symbol + ' #WhaleAlert #crypto #AlphaForgeAI';

// Trim to 280 chars
if (tweet.length > 280) tweet = tweet.substring(0, 277) + '...';

return [{ json: { ingest_payload: payload, tweet: tweet, top_alert: top, total: events.length } }];
